#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(jsonlite);library(glmnet);library(digest)})
args<-commandArgs(TRUE);m<-if(length(args))normalizePath(args[1])else normalizePath('05_organ_network/Fig4c_raw_reconstruction_20261008');root<-Sys.getenv('DISCO_INPUT_ROOT');d<-readRDS(file.path(m,'input/private/rebuilt_models_and_scores.rds'));op<-readRDS(file.path(root,'Result2/Lasso.model.prot.rds'));oj<-readRDS(file.path(root,'Result2/Lasso.model.ClinicalProt.rds'));os<-readRDS(file.path(root,'Result2/UKB.ClinicalProt.DISCO.rds'))
compare<-function(n,o){fields<-c('lambda','cvm','cvsd','cvup','cvlo');list(new_lambda_count=length(n$lambda),old_lambda_count=length(o$lambda),max_errors=setNames(lapply(fields,function(k)if(length(n[[k]])==length(o[[k]]))max(abs(n[[k]]-o[[k]]))else NULL),fields),lambda_min_new=n$lambda.min,lambda_min_old=o$lambda.min,canonical_selected_new=sub('^X','',rownames(as.matrix(coef(n,s='lambda.min')))[as.matrix(coef(n,s='lambda.min'))[,1]!=0]),canonical_selected_old=sub('^X','',rownames(as.matrix(coef(o,s='lambda.min')))[as.matrix(coef(o,s='lambda.min'))[,1]!=0]))}
cp<-compare(d$protein_fit,op);cj<-compare(d$joint_fit,oj);j<-match(d$eids,os$ID);stopifnot(!anyNA(j));delta<-d$score-os$mc[j]
write.csv(data.frame(rank=seq_along(delta),score_difference=delta),file.path(m,'results/new_vs_historical_score_difference.csv'),row.names=FALSE)
t<-read.csv(file.path(m,'tables/Fig4c_new_statistics.csv'));df<-length(d$score)-4;t$P_age_sex_correct_df<-2*pt(-abs(t$partial_r)*sqrt(df/(1-t$partial_r^2)),df=df);write.csv(t,file.path(m,'tables/Fig4c_new_statistics.csv'),row.names=FALSE)
report<-list(status='PASS_NEW_RAW_CHAIN_NOT_HISTORICAL_EXACT',protein=cp,joint=cj,protein_selected_set_identical=setequal(cp$canonical_selected_new,cp$canonical_selected_old),joint_selected_set_identical=setequal(cj$canonical_selected_new,cj$canonical_selected_old),score_max_abs_difference=max(abs(delta)),score_spearman_with_historical=cor(d$score,os$mc[j],method='spearman'),joint_feature_only_new=setdiff(cj$canonical_selected_new,cj$canonical_selected_old),joint_feature_only_historical=setdiff(cj$canonical_selected_old,cj$canonical_selected_new),historical_random_fold_ids_recovered=FALSE,source_seed=134,fold_assignment_saved_private=TRUE,tie_method='Breslow (glmnet5.0 actual default; explicitly locked in code for future5.1)',P_export='Original residual cor.test N-2 and correct age+sex partial P N-4 separately labelled',estimand='Apparent whole-cohort trained LASSO/score, not held-out prediction')
write_json(report,file.path(m,'results/historical_comparison.json'),pretty=TRUE,auto_unbox=TRUE,digits=17);print(report)
